('Ứng tuyển','application',1,'published'),('CV','cv',2,'published'),('Phỏng vấn','interview',3,'published'),('Kết quả','result',4,'published'),('Offer','offer',5,'published'),('Quyền lợi','benefits',6,'published'),('Công tác','travel',7,'published'),('Dữ liệu ứng viên','candidate-data',8,'published'),('Thông tin tuyển dụng chính thức','official-recruitment',9,'published') on conflict (slug) do nothing;
