insert into public.recruitment_steps (number, title, short_description, full_description, display_order, status) values
('BẮT ĐẦU','Khám phá cơ hội phù hợp','Tìm một công việc phù hợp với điều bạn muốn phát triển.','Khám phá các vị trí đang tuyển tại Mitalab theo nhóm nghề, địa điểm và lĩnh vực chuyên môn.',0,'published'),
('01','Gửi hồ sơ','Cho chúng tôi biết bạn là ai và điều bạn đang tìm kiếm.','Chọn vị trí phù hợp và gửi CV cùng các thông tin cần thiết.',1,'published'),
('02','Trao đổi cùng HR','Một cuộc trò chuyện để hai bên hiểu nhau hơn.','HR sẽ trao đổi về kinh nghiệm, mong muốn nghề nghiệp và thông tin quan trọng về vị trí.',2,'published'),
('03','Gặp gỡ đội ngũ chuyên môn','Cùng nói sâu hơn về công việc bạn sẽ thực sự đảm nhận.','Trao đổi với quản lý trực tiếp và đội ngũ chuyên môn về kinh nghiệm, kiến thức và kỳ vọng.',3,'published'),
('04','Nhận kết quả','Bạn sẽ được cập nhật về kết quả và bước tiếp theo.','Đội ngũ Tuyển dụng tổng hợp đánh giá và phản hồi kết quả đến bạn.',4,'published'),
('05','Đề nghị nhận việc','Khi hai bên cùng nhìn thấy một sự phù hợp.','HR trao đổi rõ về vị trí, chính sách và thời điểm dự kiến bắt đầu công việc.',5,'published'),
('06','Chào mừng bạn gia nhập Mitalab','Hành trình ứng tuyển kết thúc. Một hành trình mới bắt đầu.','Mitalab gửi các thông tin cần thiết để chuẩn bị cho ngày làm việc đầu tiên.',6,'published') on conflict do nothing;
insert into public.career_stories (slug,title,eyebrow,category,job_family,short_description,cta_label,cta_url,published_date,featured,story_type,status) values
('miseq-i100-plus','Lắp đặt MiSeq i100 Plus đầu tiên tại Việt Nam','FIELD NOTES','Technical','Technical','Một lát cắt thực tế về công việc triển khai thiết bị, bàn giao công nghệ và hỗ trợ kỹ thuật cho đối tác.','Xem câu chuyện & nguồn ↗','https://www.mitalab.com/mitalab-lap-dat-cong-nghe-giai-trinh-tu-gen-moi-miseq-i100-plus-dau-tien-tai-viet-nam.html','2026-09-04',true,'mitalab_story','published'),
('kick-off-meeting-2026','Kick-off Meeting 2026: Đồng hành phát triển','GROWING TOGETHER','Culture','All','Ghi nhận thành tích, mục tiêu BSC, cam kết đội ngũ và tinh thần học hỏi liên tục trong một năm mới.','Xem câu chuyện & nguồn ↗','https://www.mitalab.com/#news','2026-09-04',false,'mitalab_story','published'),
('team-building-2023','Team Building 2023: Trekking Together as One','TOGETHER AS ONE','Culture','All','Hành trình qua các thử thách Tâm thế, Hợp tác, Kỷ luật và Đồng nhất để kể câu chuyện văn hóa bằng trải nghiệm.','Xem câu chuyện & nguồn ↗','https://www.mitalab.com/#news','2026-09-04',false,'mitalab_story','published') on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, status = excluded.status;
insert into public.work_environment (number,title,description,evidence,reference_article,display_order,status) values
('01','Phát triển chuyên môn qua công việc','Các JD hiện hành nêu cơ hội tham gia khóa đào tạo kiến thức chuyên môn và kỹ năng mềm.','Đào tạo chuyên môn và học từ công việc thực tế.','https://www.mitalab.com/#services',1,'published'),
('02','Phát huy năng lực trong từng vai trò','Các hoạt động và tin tức Mitalab là nguồn tham khảo để tìm hiểu cách đội ngũ cùng phát triển và phối hợp.','Mục tiêu BSC, hoạt động nội bộ và trao đổi chuyên môn.','https://www.mitalab.com/#news',2,'published'),
('03','Hợp tác và chia sẻ trong công việc','Team Building Together as One truyền tải văn hóa và tinh thần đội nhóm bằng trải nghiệm.','Tâm thế, Hợp tác, Kỷ luật và Đồng nhất.','https://www.mitalab.com/mitalab-team-building-2023-trekking-together-one.html',3,'published');
