insert into public.homepage_content (id,eyebrow,headline_line_1,headline_line_2,description,cta_1_label,cta_1_url,cta_2_label,cta_2_url,metrics,status) values (true,'CAREER HUB 2027 · BẢN MẪU TƯƠNG TÁC','Khám phá cơ hội nghề nghiệp','Phát triển cùng Mitalab','Khám phá những vai trò kết nối thiết bị, dữ liệu và con người để góp phần nâng tầm chất lượng xét nghiệm tại Việt Nam.','Tìm vị trí phù hợp','#jobs','Xem quy trình tuyển dụng','#journey','[{"value":"25+","label":"Năm kinh nghiệm trên thị trường"},{"value":"800+","label":"Bệnh viện đối tác"},{"value":"500+","label":"Sản phẩm cung cấp"},{"value":"4","label":"Văn phòng làm việc trên toàn quốc"}]','published') on conflict (id) do update set eyebrow=excluded.eyebrow, headline_line_1=excluded.headline_line_1, headline_line_2=excluded.headline_line_2, description=excluded.description, metrics=excluded.metrics, status=excluded.status;
