on conflict (slug) do update set name = excluded.name, english_name = excluded.english_name, short_description = excluded.short_description, display_order = excluded.display_order, status = excluded.status;

select v.code, v.slug, v.title, c.id, v.location, 'Toàn thời gian', v.summary, v.description::jsonb, v.requirements::jsonb, '[]'::jsonb, date '2026-09-04', 'published', v.display_order
from (values
('HN-SALES','hn-sales','[HN] Nhân viên Kinh doanh Thiết bị Y tế & Hóa chất tiêu hao (Sinh hóa – Miễn dịch)','Kinh doanh & Vận hành','Hà Nội','Tìm hiểu thị trường, phát triển khách hàng và tư vấn thiết bị, hóa chất xét nghiệm phù hợp.','["Tìm hiểu thị trường, đối thủ, sản phẩm và khách hàng.","Tìm kiếm khách hàng mới và phát triển quan hệ kinh doanh.","Tư vấn sản phẩm, thiết bị phù hợp và đàm phán với khách hàng."]','["Đại học khối xét nghiệm, y dược, điện tử y sinh hoặc công nghệ sinh học.","Tối thiểu 01 năm kinh nghiệm công nghệ y tế, dược phẩm hoặc sales ETC.","Giao tiếp, đàm phán, thuyết trình tốt."]',1),
('HN-DEV','hn-developer','[HN] Nhân viên Lập trình Phần mềm','LIS / IT / Data','Hà Nội','Phát triển ứng dụng web và Windows cho dự án nội bộ và khách hàng trong Digital Healthcare/MedTech.','["Phát triển ứng dụng web và Windows.","Gỡ lỗi, sửa đổi chương trình và kết nối cơ sở dữ liệu.","Báo cáo tiến độ và xử lý lỗi khi triển khai tại khách hàng."]','["Tốt nghiệp đại học, cao đẳng ngành liên quan.","Có kinh nghiệm với Web Services, JavaScript, ReactJS, HTML.","Hiểu C#, .NET Framework và SQL Server hoặc MySQL."]',2),
('HN-ACCOUNTANT','hn-accountant','[HN] Kế toán trưởng (Không quản lý nhân viên)','Khối hỗ trợ','Hà Nội','Kiểm soát tài chính, công nợ, chứng từ, báo cáo luật định và các vấn đề thuế của Công ty.','["Kiểm tra các khoản thu chi và nghĩa vụ ngân sách.","Rà soát, đối chiếu và thu hồi công nợ.","Chịu trách nhiệm hoạt động tài chính kế toán và báo cáo theo luật định."]','["Đại học chuyên ngành Tài chính, Kế toán doanh nghiệp.","Tối thiểu 03 năm kinh nghiệm Kế toán trưởng hoặc kiểm toán Big 4.","Am hiểu pháp luật thuế và chuẩn mực tài chính kế toán."]',3),
('HN-RD','hn-rd','[HN] Nhân viên R&D (Phát triển sản phẩm thương mại)','Kinh doanh & Vận hành','Hà Nội','Nghiên cứu xu hướng xét nghiệm, tìm kiếm sản phẩm mới và phát triển cơ hội kinh doanh trong ngành y tế.','["Tìm kiếm ý tưởng sản phẩm theo chiến lược Công ty.","Nghiên cứu thị trường và xu hướng sản phẩm xét nghiệm.","Xây dựng mạng lưới với các công ty Diagnostic và triển khai thử sản phẩm mới."]','["Đại học chuyên ngành y, dược, xét nghiệm hoặc công nghệ sinh học.","Ít nhất 2 năm kinh nghiệm phát triển thị trường hoặc sản phẩm.","Có kiến thức thị trường xét nghiệm và tiếng Anh lưu loát."]',4),
('HN-TECHNICIAN','hn-technician','[HN] Kỹ thuật viên Bảo trì Bảo dưỡng Thiết bị Y tế','Thiết bị & Ứng dụng','Hà Nội','Lắp đặt, bảo trì máy xét nghiệm, khảo sát hiện trường và phối hợp xử lý sự cố tại khách hàng.','["Lắp đặt máy xét nghiệm mới.","Bảo trì, bảo dưỡng máy xét nghiệm tại khách hàng.","Phối hợp hỗ trợ kỹ sư giải quyết sự cố và khảo sát hiện trường."]','["Cao đẳng/Đại học Điện tử, Điện tử y sinh, Điện tử viễn thông hoặc Tự động hóa.","Không yêu cầu kinh nghiệm, chấp nhận sinh viên mới ra trường.","Đọc hiểu tài liệu kỹ thuật tiếng Anh và sẵn sàng đi công tác."]',5),
('HN-AUTOMATION','hn-automation','[HN] Nhân viên Phụ trách Sản phẩm (Ngành hàng Automation)','Kinh doanh & Vận hành','Hà Nội','Quản lý danh mục Automation & AI, phát triển thị trường, hỗ trợ kinh doanh và triển khai giải pháp.','["Quản lý danh mục sản phẩm và giải pháp Automation, AI.","Phân tích thị trường, khách hàng và xu hướng công nghệ.","Tư vấn, xây dựng và trình bày giải pháp Automation và AI."]','["Đại học chuyên ngành y, dược, xét nghiệm, công nghệ sinh học, điện tử y sinh hoặc tự động hóa.","Ít nhất 03 năm kinh nghiệm phát triển sản phẩm hoặc tư vấn giải pháp.","Có kiến thức tự động hóa và phân tích dữ liệu tốt."]',6),
('HN-ENGINEER','hn-engineer','[HN] Kỹ sư Bảo trì Bảo dưỡng Thiết bị Y tế','Thiết bị & Ứng dụng','Hà Nội','Lắp đặt, bảo trì và bảo dưỡng thiết bị xét nghiệm tại khu vực được phân công, phối hợp hỗ trợ khách hàng.','["Lắp đặt máy xét nghiệm mới.","Bảo trì, bảo dưỡng máy xét nghiệm tại khách hàng.","Phối hợp hỗ trợ kỹ sư giải quyết sự cố và khảo sát hiện trường."]','["Cao đẳng/Đại học Điện tử, Điện tử y sinh, Điện tử viễn thông hoặc Tự động hóa.","Ứng viên có từ 1 năm kinh nghiệm trở lên.","Đọc hiểu tài liệu kỹ thuật tiếng Anh và sẵn sàng đi công tác."]',7)
) as v(code,slug,title,category,location,summary,description,requirements,display_order)
join public.job_categories c on c.name = v.category
on conflict (code) do update set title = excluded.title, category_id = excluded.category_id, location = excluded.location, short_description = excluded.short_description, description = excluded.description, requirements = excluded.requirements, display_order = excluded.display_order, status = excluded.status;


select v.question, v.answer, c.id, v.display_order, true, 'published' from (values
('Mình muốn ứng tuyển thì bắt đầu từ đâu?','Bạn hãy chọn vị trí phù hợp, đọc kỹ JD và gửi CV theo đúng hướng dẫn trên JD Mitalab. Career Hub này không nhận hồ sơ thay cho kênh chính thức.',1),
('Mình có thể ứng tuyển nhiều vị trí cùng lúc không?','Có. Bạn chỉ cần ghi rõ vị trí ưu tiên số 1 để đội ngũ Tuyển dụng hiểu định hướng của mình.',2),
('Mitalab có cơ hội cho intern hoặc sinh viên mới ra trường không?','Điều này tùy từng JD. Bạn có thể đăng ký Talent Community để nhận thông tin sớm khi có vị trí phù hợp.',3),
('Các vị trí hiện làm việc ở đâu?','Mitalab có văn phòng tại Hà Nội, TP.HCM, Đà Nẵng và Cần Thơ. Một số vai trò field service sẽ cần di chuyển.',4),
('Mình chưa học y khoa thì có ứng tuyển được không?','Bạn vẫn có thể ứng tuyển nếu phù hợp với yêu cầu JD. Mỗi nhóm nghề có nền tảng ưu tiên khác nhau.',5),
('Sau khi gửi hồ sơ, bao lâu mình sẽ nhận được phản hồi?','Mitalab xác nhận hồ sơ ngay khi tiếp nhận; sàng lọc trong khoảng ≤3 ngày làm việc và cập nhật kết quả theo từng bước.',6),
('Nếu chưa thấy vị trí phù hợp thì mình nên làm gì?','Bạn có thể đăng ký Talent Community để Mitalab có cơ sở kết nối khi xuất hiện cơ hội phù hợp.',7)
) as v(question,answer,display_order) join public.faq_categories c on c.slug = 'application' on conflict do nothing;





